function _ComputeLocalExtent(width: number, height: number): Extent {
  const max: [number, number, number] =
    [Math.fround(width * 0.5), Math.fround(height * 0.5), 0.0]
  return [[-max[0], -max[1], -max[2]], max]
}

// rectLight.cpp:198-232. Attribute values are read as float, and the extent
// is a VtVec3fArray (computeExtentFromPlugins rounds the result to float).
function _ComputeExtent(prim: Prim, time?: number, transform?: Matrix4): Extent | null {
  const light = new RectLight(prim)

  const width = _GetFloat(light.getWidthAttr(), time)
  if (width === undefined) {
    return null
  }

  const height = _GetFloat(light.getHeightAttr(), time)
  if (height === undefined) {
    return null
  }

  const extent = _ComputeLocalExtent(width, height)

  if (transform) {
    const bbox = new GfBBox3d(new GfRange3d(new GfVec3d(...extent[0]), new GfVec3d(...extent[1])),
      new GfMatrix4d(...transform))
    const range = bbox.ComputeAlignedRange()
    return [[...range.getMin().data], [...range.getMax().data]] as Extent
  }

  return extent
}

// UsdAttribute::Get<float>(&value, time): fails when there is no value.
function _GetFloat(attr: Attribute | undefined, time?: number): number | undefined {
  const value = time === undefined ? attr?.getValue() : attr?.getValueAtTime(time)
  return typeof value === 'number' ? Math.fround(value) : undefined
}

